) as v(
  nume_normalizat, nume_client, tip_venit, produs, serviciu, luna,
  venit_estimat, venit_realizat, facturat, observatii, are_contract, ctr_produs, ctr_serviciu
)
join public.partners p on p.nume_normalizat = v.nume_normalizat
left join public.contracte ctr
  on ctr.partner_id = p.id
  and ctr.produs = v.ctr_produs
  and ctr.serviciu = v.ctr_serviciu
  and v.are_contract = true;

insert into public.venituri_linii (
  partner_id, nume_client, tip_venit, produs, serviciu, luna,
  venit_estimat, venit_realizat, facturat, observatii, contract_id
)
select
  partner_id, nume_client, tip_venit, produs, serviciu, luna,
  venit_estimat, venit_realizat, facturat, observatii, contract_id
from tmp_venit_import;

